fact.expression:
let $cases := doc("third_party/qt4tests/catalog.xml")/*:catalog/*:test-set ! doc(resolve-uri(@file, base-uri(.)))//*:test-case
let $applies := fn($case, $language) {
  let $spec := ($case/*:dependency[@type = "spec"], $case/../*:dependency[@type = "spec"])[1]
  return empty($spec) or (some $token in tokenize($spec/@value) satisfies
    let $version := xs:integer(replace($token, "^..(\d+)\+?$", "$1"))
    return substring($token, 1, 2) = $language and ($version = 40 or (ends-with($token, "+") and $version le 40)))
}
return count(distinct-values($cases[$applies(., "XQ")] ! base-uri(.)))
